-- Ocarina of Time Remake's category list and adult trading sequence as Jess left
-- them on 2026-11-14, with the history of each change (Map Settings' and the
-- markers'), as they were made:
--  * a Trading Sequence category (Points of Interest) holding ten of the trade
--    items, each written out by Jess, linking on to the next (Biggoron's Sword
--    stays in Weapons)
--  * Key Items (was Tools & Quest Items) with a key, Treasure Chests (Weapons,
--    Shields, Equip., Misc), the item categories restyled
--  * a Dungeon Items section: Dungeon Maps, Compasses, Small Keys, Boss Keys and
--    Boss Doors
--  * every category under its section's own category (ajax/map_settings_layout.php)
-- Trading Sequence and Dungeon Items are looked up by name: their ids here
-- needn't match. A trading marker anyone has edited since 2026-11-13 (other
-- than the remake renames) is left as it is.

-- The two categories this adds, if they aren't there yet (ootr_trading_path makes
-- Trading Sequence first).
INSERT INTO marker_category (parent_id, marker_category_type_id, container_id, name, default_checked, img, color, visible_zoom, visible, custom_style, shape, glyph_color, slug) SELECT 64040, 1, 64, 'Trading Sequence', 1, 'BotW_Side-Quest', '#ffad47', 0, 1, 1, 'circle', '#ffffff', '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_category WHERE container_id = 64 AND name = 'Trading Sequence' AND parent_id IS NOT NULL);
INSERT INTO marker_category (parent_id, marker_category_type_id, container_id, name, default_checked, img, color, visible_zoom, visible, custom_style, slug) SELECT NULL, 1, 64, 'Dungeon Items', 1, 'BotW_Dungeon', '#4bc5ee', 0, 1, 0, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_category WHERE container_id = 64 AND name = 'Dungeon Items' AND parent_id IS NULL);
SET @trading := (SELECT id FROM marker_category WHERE container_id = 64 AND name = 'Trading Sequence' AND parent_id IS NOT NULL ORDER BY id LIMIT 1);
SET @dungeon := (SELECT id FROM marker_category WHERE container_id = 64 AND name = 'Dungeon Items' AND parent_id IS NULL ORDER BY id LIMIT 1);

