INSERT INTO marker_revision (marker_id, user_id, action, summary, reverts_revision_id, data, created) SELECT 64705014, 15, 'edit', NULL, NULL, REPLACE(REPLACE('{"title":"Biggoron\\u2019s Sword","description":"","categoryId":64061,"submapId":650001,"x":159.102,"y":-92.971,"z":null,"global":0,"visible":1,"tabs":["<p>Three days after delivering the eye drops, show the Biggoron Receipt to Biggoron at the top of Death Mountain Trail to collect Biggoron&rsquo;s Sword.<\\/p>\\r\\n<p>It&rsquo;s the strongest sword in the game, twice as strong as the Master Sword, but it takes both hands, so you can&rsquo;t use a shield while it&rsquo;s out.<\\/p>\\r\\n<p><em>Adult Link<\\/em><\\/p>"]}', '"__TRADING__"', @trading), '"__DUNGEON__"', @dungeon), '2026-11-14 22:15:36' FROM DUAL WHERE @ok64705014 = 1;
