UPDATE marker_tab SET tab_text = '&lt;p&gt;Three days after delivering the eye drops, show the Biggoron Receipt to Biggoron at the top of Death Mountain Trail to collect Biggoron&amp;rsquo;s Sword.&lt;/p&gt;\r\n&lt;p&gt;It&amp;rsquo;s the strongest sword in the game, twice as strong as the Master Sword, but it takes both hands, so you can&amp;rsquo;t use a shield while it&amp;rsquo;s out.&lt;/p&gt;\r\n&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;' WHERE marker_id = 64705014 AND visible = 1 AND @ok64705014 = 1;
